//! Token faucet dispensing a fixed amount per address with a cooldown.
//!
//! * **Dispense** — any address may call `claim` to receive a fixed
//!   `amount_per_claim` of the configured token.
//! * **Cooldown** — an address must wait `cooldown_seconds` between
//!   successive claims; claiming before the cooldown elapses panics.
//!
//! * **Admin handover** — `propose_admin` / `accept_admin` move the admin role
//!   in two steps; `cancel_admin_proposal` withdraws a pending offer.
//!
//! Generated by [soroban-forge](https://github.com/soroban-forge-labs/soroban-forge).

#![no_std]

use soroban_sdk::{
    contract, contracterror, contractevent, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    AlreadyInitialized = 1,
    AmountPerClaimMustBePositive = 2,
    WithdrawalAmountMustBePositive = 3,
    CooldownNotElapsed = 4,
}

pub const DAY_IN_LEDGERS: u32 = 17_280;
/// Instance storage (admin and faucet settings) is bumped to this many ledgers
/// on every state-changing call so the contract is not archived while in use.
pub const INSTANCE_TTL: u32 = 30 * DAY_IN_LEDGERS;
pub const INSTANCE_TTL_THRESHOLD: u32 = INSTANCE_TTL - DAY_IN_LEDGERS;

fn extend_instance(env: &Env) {
    env.storage()
        .instance()
        .extend_ttl(INSTANCE_TTL_THRESHOLD, INSTANCE_TTL);
}

#[contracttype]
pub enum DataKey {
    Admin,
    /// Address offered the admin role, awaiting `accept_admin`.
    PendingAdmin,
    Token,
    AmountPerClaim,
    CooldownSeconds,
    LastClaim(Address),
}

/// `admin` offered the admin role to `new_admin`.
#[contractevent]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AdminProposed {
    #[topic]
    pub admin: Address,
    pub new_admin: Address,
}

/// `new_admin` accepted the handover and replaced `old_admin`.
#[contractevent]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AdminTransferred {
    #[topic]
    pub old_admin: Address,
    pub new_admin: Address,
}

/// The pending handover to `new_admin` was cancelled by `admin`.
#[contractevent]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AdminProposalCancelled {
    #[topic]
    pub admin: Address,
    pub new_admin: Address,
}

#[contract]
pub struct FaucetContract;

#[contractimpl]
impl FaucetContract {
    /// Initialize the faucet.
    ///
    /// * `admin` — address that funds the faucet with tokens
    /// * `token` — contract address of the SEP-41 token to dispense
    /// * `amount_per_claim` — fixed amount sent on every successful claim
    /// * `cooldown_seconds` — minimum time an address must wait between claims
    pub fn initialize(
        env: Env,
        admin: Address,
        token: Address,
        amount_per_claim: i128,
        cooldown_seconds: u64,
    ) {
        // Runs once: otherwise anyone could re-initialize with themselves as
        // admin, `amount_per_claim` equal to the whole balance and no
        // cooldown, then drain the faucet in a single claim.
        if env.storage().instance().has(&DataKey::Admin) {
            panic_with_error!(&env, Error::AlreadyInitialized);
        }
        admin.require_auth();

        if amount_per_claim <= 0 {
            panic_with_error!(&env, Error::AmountPerClaimMustBePositive);
        }

        env.storage().instance().set(&DataKey::Admin, &admin);
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage()
            .instance()
            .set(&DataKey::AmountPerClaim, &amount_per_claim);
        env.storage()
            .instance()
            .set(&DataKey::CooldownSeconds, &cooldown_seconds);
        extend_instance(&env);
    }

    /// Deposit tokens into the faucet.
    ///
    /// Must be called by the `admin`; may be called repeatedly to top up.
    pub fn fund(env: Env, amount: i128) {
        extend_instance(&env);
        let admin: Address = env.storage().instance().get(&DataKey::Admin).unwrap();
        admin.require_auth();

        let token: Address = env.storage().instance().get(&DataKey::Token).unwrap();
        let client = token::Client::new(&env, &token);
        client.transfer(&admin, &env.current_contract_address(), &amount);
    }

    /// Step one of a two-step admin handover. Current admin only.
    ///
    /// Nothing changes until `new_admin` calls `accept_admin`, so a mistyped
    /// address cannot lock the admin out. Proposing again replaces any
    /// earlier pending proposal.
    pub fn propose_admin(env: Env, new_admin: Address) {
        let admin = env
            .storage()
            .instance()
            .get::<_, Address>(&DataKey::Admin)
            .unwrap();
        admin.require_auth();
        env.storage()
            .instance()
            .set(&DataKey::PendingAdmin, &new_admin);
        AdminProposed { admin, new_admin }.publish(&env);
    }

    /// Step two: the pending admin takes over. Requires authorization from
    /// the address named in `propose_admin`.
    pub fn accept_admin(env: Env) {
        let new_admin: Address = env
            .storage()
            .instance()
            .get(&DataKey::PendingAdmin)
            .unwrap_or_else(|| panic!("no pending admin"));
        new_admin.require_auth();
        let old_admin = env
            .storage()
            .instance()
            .get::<_, Address>(&DataKey::Admin)
            .unwrap();
        env.storage().instance().set(&DataKey::Admin, &new_admin);
        env.storage().instance().remove(&DataKey::PendingAdmin);
        AdminTransferred {
            old_admin,
            new_admin,
        }
        .publish(&env);
    }

    /// Cancel a pending handover. Current admin only.
    pub fn cancel_admin_proposal(env: Env) {
        let admin = env
            .storage()
            .instance()
            .get::<_, Address>(&DataKey::Admin)
            .unwrap();
        admin.require_auth();
        let new_admin: Address = env
            .storage()
            .instance()
            .get(&DataKey::PendingAdmin)
            .unwrap_or_else(|| panic!("no pending admin"));
        env.storage().instance().remove(&DataKey::PendingAdmin);
        AdminProposalCancelled { admin, new_admin }.publish(&env);
    }

    /// The address offered the admin role, if a handover is pending.
    pub fn pending_admin(env: Env) -> Option<Address> {
        env.storage().instance().get(&DataKey::PendingAdmin)
    }

    pub fn withdraw(env: Env, amount: i128) {
        extend_instance(&env);
        let admin: Address = env.storage().instance().get(&DataKey::Admin).unwrap();
        admin.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::WithdrawalAmountMustBePositive);
        }
        let token: Address = env.storage().instance().get(&DataKey::Token).unwrap();
        token::Client::new(&env, &token).transfer(&env.current_contract_address(), &admin, &amount);
    }

    pub fn set_params(env: Env, amount_per_claim: i128, cooldown_seconds: u64) {
        extend_instance(&env);
        let admin: Address = env.storage().instance().get(&DataKey::Admin).unwrap();
        admin.require_auth();
        if amount_per_claim <= 0 {
            panic_with_error!(&env, Error::AmountPerClaimMustBePositive);
        }
        env.storage()
            .instance()
            .set(&DataKey::AmountPerClaim, &amount_per_claim);
        env.storage()
            .instance()
            .set(&DataKey::CooldownSeconds, &cooldown_seconds);
    }

    /// Claim the fixed dispense amount.
    ///
    /// Requires authorization from `to`. Reverts if `to` claimed within the
    /// last `cooldown_seconds`.
    pub fn claim(env: Env, to: Address) -> i128 {
        to.require_auth();
        extend_instance(&env);

        let now = env.ledger().timestamp();
        let cooldown: u64 = env
            .storage()
            .instance()
            .get(&DataKey::CooldownSeconds)
            .unwrap();

        let key = DataKey::LastClaim(to.clone());
        if let Some(last_claim) = env.storage().persistent().get::<_, u64>(&key) {
            if now < last_claim + cooldown {
                panic_with_error!(&env, Error::CooldownNotElapsed);
            }
        }

        env.storage().persistent().set(&key, &now);
        env.storage()
            .persistent()
            .extend_ttl(&key, 17_280 * 29, 17_280 * 30);

        let amount: i128 = env
            .storage()
            .instance()
            .get(&DataKey::AmountPerClaim)
            .unwrap();

        let token: Address = env.storage().instance().get(&DataKey::Token).unwrap();
        let client = token::Client::new(&env, &token);
        client.transfer(&env.current_contract_address(), &to, &amount);

        amount
    }

    /// Return the timestamp at which `addr` may next successfully claim.
    pub fn next_claim_time(env: Env, addr: Address) -> u64 {
        let cooldown: u64 = env
            .storage()
            .instance()
            .get(&DataKey::CooldownSeconds)
            .unwrap();
        match env
            .storage()
            .persistent()
            .get::<_, u64>(&DataKey::LastClaim(addr))
        {
            Some(last_claim) => last_claim + cooldown,
            None => 0,
        }
    }
}

